const MILLISECOND = 1
const SECOND = 1000 * MILLISECOND
const MINUTE = 60 * SECOND
const HOUR = 60 * MINUTE
const DAY = 24 * HOUR

// How far back and forward we keep talking in words ("5 days ago") before
// falling back to a plain date ("Sep 12").
const WORDS_WINDOW_IN_DAYS = 6

const FORMATS = {
  time: new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" }),
  date: new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" }),
  fullDate: new Intl.DateTimeFormat("en-US", { weekday: "long", year: "numeric", month: "long", day: "numeric" }),
  shortDate: new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" }),
  shortDateWithYear: new Intl.DateTimeFormat("en-US", { year: "numeric", month: "short", day: "numeric" }),
  stamp: new Intl.DateTimeFormat("en-US", { year: "numeric", month: "short", day: "numeric" }),
  shortDateTime: new Intl.DateTimeFormat("en-US", { year: "2-digit", month: "numeric", day: "numeric", hour: "numeric", minute: "2-digit" }),
  fullDateTime: new Intl.DateTimeFormat("en-US", { weekday: "long", year: "numeric", month: "long", day: "numeric", hour: "numeric", minute: "2-digit" })
}

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / DAY)
}

export function beginningOfDay(date) {
  const { year, month, day } = datePartsInLocalTimezone(date)
  return new Date(year, month - 1, day)
}

// Turns a raw timestamp into words, in the timezone the browser is running in.
// A timestamp carrying an offset ("2025-09-15T13:42:00-07:00") is an instant and
// gets converted; a bare date ("2025-09-15") is a calendar day and is kept as is.
export function formatTime(timestamp, format = "relative") {
  const date = parseTimestamp(timestamp)

  if (!date) return ""

  switch (format) {
    case "time": return FORMATS.time.format(date)
    case "date": return FORMATS.date.format(date)
    case "full_date": return FORMATS.fullDate.format(date)
    case "short_date": return shortDate(date)
    case "stamp": return FORMATS.stamp.format(date)
    case "short_datetime": return FORMATS.shortDateTime.format(date)
    case "full_datetime": return FORMATS.fullDateTime.format(date)
    default: return relativeTime(date)
  }
}

export function relativeTime(date, now = new Date()) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
    if (date.getTime() <= now.getTime()) return FORMATS.time.format(date)
    return inTime(date, now)
  }

  if (days === 1) return "tomorrow"
  if (days > 1) return days <= WORDS_WINDOW_IN_DAYS ? `in ${days} days` : shortDate(date)
  if (days === -1) return "yesterday"

  return days >= -WORDS_WINDOW_IN_DAYS ? `${-days} days ago` : shortDate(date)
}

// The longest form we have, for tooltips and screen readers: what a timestamp
// looks like spelled out in full.
export function formatFullTime(timestamp) {
  const date = parseTimestamp(timestamp)

  if (!date) return ""

  return isDateOnly(timestamp) ? FORMATS.fullDate.format(date) : FORMATS.fullDateTime.format(date)
}

function inTime(date, now) {
  const elapsed = date.getTime() - now.getTime()

  if (elapsed < HOUR) return `in ${duration(elapsed, MINUTE, "minute")}`
  return `in ${duration(elapsed, HOUR, "hour")}`
}

function duration(elapsed, unit, name) {
  const amount = Math.max(1, Math.round(elapsed / unit))
  return amount === 1 ? `1 ${name}` : `${amount} ${name}s`
}

function shortDate(date) {
  if (date.getFullYear() === new Date().getFullYear()) {
    return FORMATS.shortDate.format(date)
  } else {
    return FORMATS.shortDateWithYear.format(date)
  }
}

function parseTimestamp(timestamp) {
  if (timestamp instanceof Date) return timestamp

  if (isDateOnly(timestamp)) {
    const [ year, month, day ] = timestamp.split("-").map(part => parseInt(part, 10))
    return new Date(year, month - 1, day)
  }

  const date = new Date(timestamp)
  return Number.isNaN(date.getTime()) ? null : date
}

function isDateOnly(timestamp) {
  return /^\d{4}-\d{2}-\d{2}$/.test(timestamp)
}

function datePartsInLocalTimezone(date) {
  return { year: date.getFullYear(), month: date.getMonth() + 1, day: date.getDate() }
}
