  shortDateWithYear: new Intl.DateTimeFormat("en-US", { year: "numeric", month: "short", day: "numeric" }),
  stamp: new Intl.DateTimeFormat("en-US", { year: "numeric", month: "short", day: "numeric" }),
  shortDateTime: new Intl.DateTimeFormat("en-US", { year: "2-digit", month: "numeric", day: "numeric", hour: "numeric", minute: "2-digit" }),
  fullDateTime: new Intl.DateTimeFormat("en-US", { weekday: "long", year: "numeric", month: "long", day: "numeric", hour: "numeric", minute: "2-digit" })
}

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / DAY)
}

export function beginningOfDay(date) {
  const { year, month, day } = datePartsInLocalTimezone(date)
  return new Date(year, month - 1, day)
}

